import TestimonialsSectionV5 from "./components/testimonials-section-v5"

export default function Page() {
  return <TestimonialsSectionV5 />
}

import { Badge } from "@/components/ui/badge"

import TestimonialCard from "./testimonial-card"
import { sectionMeta, testimonials } from "../lib/testimonials-content"

export default function TestimonialsSectionV5() {
  return (
    <section className="py-4 md:py-6 lg:py-8">
      <div className="mx-auto max-w-6xl px-4">
        <div className="flex flex-col items-center gap-4 text-center">
          <Badge variant="secondary">{sectionMeta.badge}</Badge>
          <h2 className="text-4xl font-medium tracking-tighter sm:text-5xl">
            {sectionMeta.title}
          </h2>
          <p className="max-w-lg text-sm leading-relaxed text-muted-foreground md:text-base">
            {sectionMeta.description}
          </p>
        </div>

        <div className="mt-10 columns-1 gap-4 sm:columns-2 md:mt-12 lg:mt-14 lg:columns-3">
          {testimonials.map((testimonial) => (
            <TestimonialCard key={testimonial.id} testimonial={testimonial} />
          ))}
        </div>
      </div>
    </section>
  )
}

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"

import type { Testimonial } from "../lib/testimonials-content"

export default function TestimonialCard({
  testimonial,
}: {
  testimonial: Testimonial
}) {
  return (
    <article className="mb-4 break-inside-avoid rounded-lg border border-border bg-muted p-5 dark:bg-background md:p-6">
      <p className="text-sm leading-relaxed text-foreground">
        {testimonial.quote}
      </p>
      <div className="mt-5 flex items-center gap-3">
        <Avatar>
          <AvatarImage
            src={testimonial.avatarSrc}
            alt={testimonial.name}
            className="object-cover object-center"
          />
          <AvatarFallback>{testimonial.initials}</AvatarFallback>
        </Avatar>
        <p className="text-sm font-medium">{testimonial.name}</p>
      </div>
    </article>
  )
}
